// 1. Configuration Validation
if (rs_config.enable != 0 && rs_config.enable != 1) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0;
    rs_output.outage = 0;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}
if (rs_config.residual_weight_floor_rad <= 0.0) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0;
    rs_output.outage = 0;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}
if (rs_config.output_alpha <= 0.0 || rs_config.output_alpha > 1.0) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0;
    rs_output.outage = 0;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}
if (rs_config.switch_confirm_cycles < 1 || rs_config.switch_confirm_cycles > 20) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0;
    rs_output.outage = 0;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}
if (rs_config.max_outage_cycles < 1 || rs_config.max_outage_cycles > 20) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0;
    rs_output.outage = 0;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}
if (rs_config.fuse_angle_rad > ADCS_PI) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0;
    rs_output.outage = 0;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}

// 2. Source Usability Check
adcs_quat_t star_norm, triad_norm;
int star_usable = 0;
int triad_usable = 0;
double star_res = rs_input.star_residual_rad;
double triad_res = rs_input.triad_residual_rad;

if (rs_input.star_q_bi != NULL && isfinite(star_res) && star_res >= 0.0) {
    if (adcs_quat_normalize(rs_input.star_q_bi, &star_norm) == ADCS_OK) {
        if (star_res <= rs_config.max_residual_rad) {
            star_usable = 1;
        }
    }
}

if (rs_input.triad_q_bi != NULL && isfinite(triad_res) && triad_res >= 0.0) {
    if (adcs_quat_normalize(rs_input.triad_q_bi, &triad_norm) == ADCS_OK) {
        if (triad_res <= rs_config.max_residual_rad) {
            triad_usable = 1;
        }
    }
}

// 3. Primary/Candidate Management
unint32 current_outage = rs_state.outage;

// Handle Outage/Fault Latching
if (!star_usable && !triad_usable) {
    current_outage++;
    if (current_outage >= rs_config.max_outage_cycles) {
        rs_output.source = RS_FAULT;
        rs_output.primary = RS_NONE;
        rs_output.candidate = RS_NONE;
        rs_output.candidate_good = 0;
        rs_output.outage = current_outage;
        rs_output.disagreement_rad = 0.0;
        rs_output.star_weight = 0.0;
        rs_output.triad_weight = 0.0;
        rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        rs_state.outage = current_outage;
        return;
    }
    rs_state.outage = current_outage;

    rs_output.source = RS_NONE;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0;
    rs_output.outage = current_outage;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};

    rs_state.previous_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
} else {
    current_outage = 0;
    rs_state.outage = 0;
}

// Determine New Primary
rs_source_t old_primary = rs_state.primary;
rs_source_t temp_primary = old_primary;

if (old_primary == RS_STAR && !star_usable) {
    if (triad_usable) temp_primary = RS_TRIAD;
} else if (old_primary == RS_TRIAD && !triad_usable) {
    if (star_usable) temp_primary = RS_STAR;
} else if (old_primary == RS_NONE) {
    if (star_usable) temp_primary = RS_STAR;
    else if (triad_usable) temp_primary = RS_TRIAD;
}

// Switch Margin Logic
if (temp_primary == old_primary && star_usable && triad_usable) {
    if (old_primary == RS_STAR) {
        if (triad_res <= star_res - rs_config.switch_margin_rad) {
            rs_state.candidate_good++;
        } else {
            rs_state.candidate_good = 0;
        }
        if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
            temp_primary = RS_TRIAD;
            rs_state.candidate_good = 0;
        }
    } else if (old_primary == RS_TRIAD) {
        if (star_res <= triad_res - rs_config.switch_margin_rad) {
            rs_state.candidate_good++;
        } else {
            rs_state.candidate_good = 0;
        }
        if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
            temp_primary = RS_STAR;
            rs_state.candidate_good = 0;
        }
    }
}

rs_source_t new_primary = temp_primary;
rs_source_t new_candidate = (new_primary == RS_STAR) ? RS_TRIAD : ((new_primary == RS_TRIAD) ? RS_STAR : RS_NONE);

rs_state.primary = new_primary;
rs_state.candidate = new_candidate;

// 4. Fusion or Primary Selection
adcs_quat_t selected_q = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
rs_source_t final_source = RS_NONE;
double disc_rad = 0.0;

if (star_usable && triad_usable) {
    double dot = adcs_quat_abs_dot(&star_norm, &triad_norm);
    if (dot > 1.0) dot = 1.0;
    disc_rad = 2.0 * acos(dot);
    rs_output.disagreement_rad = disc_rad;

    if (disc_rad <= rs_config.fuse_angle_rad) {
        final_source = RS_FUSED;

        double signed_dot = star_norm.w * triad_norm.w + star_norm.x * triad_norm.x + 
                            star_norm.y * triad_norm.y + star_norm.z * triad_norm.z;
        adcs_quat_t triad_aligned = triad_norm;
        if (signed_dot < 0.0) {
            triad_aligned.w = -triad_norm.w;
            triad_aligned.x = -triad_norm.x;
            triad_aligned.y = -triad_norm.y;
            triad_aligned.z = -triad_norm.z;
        }

        double w_star = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
        double w_triad = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);

        adcs_quat_t weighted_q;
        weighted_q.w = w_star * star_norm.w + w_triad * triad_aligned.w;
        weighted_q.x = w_star * star_norm.x + w_triad * triad_aligned.x;
        weighted_q.y = w_star * star_norm.y + w_triad * triad_aligned.y;
        weighted_q.z = w_star * star_norm.z + w_triad * triad_aligned.z;

        adcs_quat_normalize(&weighted_q, &selected_q);

        rs_output.star_weight = w_star;
        rs_output.triad_weight = w_triad;
    } else {
        final_source = new_primary;
        if (new_primary == RS_STAR) {
            selected_q = star_norm;
        } else {
            selected_q = triad_norm;
        }
        rs_output.star_weight = 0.0;
        rs_output.triad_weight = 0.0;
    }
} else {
    final_source = new_primary;
    if (new_primary == RS_STAR) {
        selected_q = star_norm;
    } else {
        selected_q = triad_norm;
    }
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
}

rs_output.source = final_source;
rs_output.primary = new_primary;
rs_output.candidate = new_candidate;
rs_output.outage = current_outage;

// 5. Post-Processing: Blend with Previous
double signed_prev_dot = selected_q.w * rs_state.previous_q_bi.w + 
                         selected_q.x * rs_state.previous_q_bi.x + 
                         selected_q.y * rs_state.previous_q_bi.y + 
                         selected_q.z * rs_state.previous_q_bi.z;

adcs_quat_t aligned_selected = selected_q;
if (signed_prev_dot < 0.0) {
    aligned_selected.w = -selected_q.w;
    aligned_selected.x = -selected_q.x;
    aligned_selected.y = -selected_q.y;
    aligned_selected.z = -selected_q.z;
}

adcs_quat_t blended;
blended.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w + rs_config.output_alpha * aligned_selected.w;
blended.x = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x + rs_config.output_alpha * aligned_selected.x;
blended.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y + rs_config.output_alpha * aligned_selected.y;
blended.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z + rs_config.output_alpha * aligned_selected.z;

adcs_quat_normalize(&blended, &rs_output.q_bi);

rs_state.previous_q_bi = rs_output.q_bi;

