    } else {
        rs_state.outage = 0;
    }

    /* 6. Fusion and Output */
    rs_output.source = next_primary;
    adcs_quat_t selected_q = {1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;

    if (next_primary == RS_STAR && star_usable_now && triad_usable_now) {
        double abs_dot = adcs_quat_abs_dot(&star_q_norm, &triad_q_norm);
        if (abs_dot > 1.0) abs_dot = 1.0;
        double disc = 2.0 * acos(abs_dot);
        rs_output.disagreement_rad = disc;

        if (disc <= rs_config.fuse_angle_rad) {
            rs_output.source = RS_FUSED;
            // Sign align TRIAD to STAR
            adcs_quat_t t_aligned = triad_q_norm;
            double sd = star_q_norm.w * triad_q_norm.w + star_q_norm.x * triad_q_norm.x + 
                        star_q_norm.y * triad_q_norm.y + star_q_norm.z * triad_q_norm.z;
            if (sd < 0.0) {
                t_aligned.w = -triad_q_norm.w;
                t_aligned.x = -triad_q_norm.x;
                t_aligned.y = -triad_q_norm.y;
                t_aligned.z = -triad_q_norm.z;
            }

            double w_s = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
            double w_t = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

            rs_output.star_weight = w_s;
            rs_output.triad_weight = w_t;

            adcs_quat_t raw = {w_s * star_q_norm.w + w_t * t_aligned.w,
                               w_s * star_q_norm.x + w_t * t_aligned.x,
                               w_s * star_q_norm.y + w_t * t_aligned.y,
                               w_s * star_q_norm.z + w_t * t_aligned.z};
