    double sel_prev_dot = selected_q.w * rs_state.previous_q_bi.w + 
                          selected_q.x * rs_state.previous_q_bi.x + 
                          selected_q.y * rs_state.previous_q_bi.y + 
                          selected_q.z * rs_state.previous_q_bi.z;

    adcs_quat_t aligned_sel = selected_q;
    if (sel_prev_dot < 0.0) {
        aligned_sel.w = -selected_q.w;
        aligned_sel.x = -selected_q.x;
        aligned_sel.y = -selected_q.y;
        aligned_sel.z = -selected_q.z;
    }

    rs_output.q_bi.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w + 
                       rs_config.output_alpha * aligned_sel.w;
    rs_output.q_bi.x = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x + 
                       rs_config.output_alpha * aligned_sel.x;
    rs_output.q_bi.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y + 
                       rs_config.output_alpha * aligned_sel.y;
    rs_output.q_bi.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z + 
                       rs_config.output_alpha * aligned_sel.z;

    if (adcs_quat_normalize(&rs_output.q_bi, &rs_output.q_bi) != ADCS_OK) {
        rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    }

    rs_state.previous_q_bi = rs_output.q_bi;
    return;

