            if (star_usable_now && rs_state.primary != RS_STAR) {
                next_primary = RS_STAR;
                primary_changed = 1;
            } else if (triad_usable_now && rs_state.primary != RS_TRIAD) {
                next_primary = RS_TRIAD;
                primary_changed = 1;
            } else {
