candidates.raw:
// 1. Configuration Validation
int config_valid = 1;
if (rs_config.enable != 0 && rs_config.enable != 1) {
    config_valid = 0;
}
if (rs_config.residual_weight_floor_rad <= 0.0) {
    config_valid = 0;
}
if (rs_config.output_alpha <= 0.0 || rs_config.output_alpha > 1.0) {
    config_valid = 0;
}
if (rs_config.switch_confirm_cycles < 1 || rs_config.switch_confirm_cycles > 20) {
    config_valid = 0;
}
if (rs_config.max_outage_cycles < 1 || rs_config.max_outage_cycles > 20) {
    config_valid = 0;
}
if (rs_config.fuse_angle_rad > ADCS_PI) {
    config_valid = 0;
}

if (!config_valid) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0;
    rs_output.outage = 0;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}

// 2. Usability Check
adcs_quat_t star_q_norm = {0}, triad_q_norm = {0};
int star_usable = 0;
int triad_usable = 0;

if (rs_input.star_q_bi != NULL) {
    adcs_status_t st = adcs_quat_normalize(rs_input.star_q_bi, &star_q_norm);
    if (st == ADCS_OK && isfinite(rs_input.star_residual_rad) && 
        rs_input.star_residual_rad >= 0.0 && 
        rs_input.star_residual_rad <= rs_config.max_residual_rad) {
        star_usable = 1;
    }
}

if (rs_input.triad_q_bi != NULL) {
    adcs_status_t st = adcs_quat_normalize(rs_input.triad_q_bi, &triad_q_norm);
    if (st == ADCS_OK && isfinite(rs_input.triad_residual_rad) && 
        rs_input.triad_residual_rad >= 0.0 && 
        rs_input.triad_residual_rad <= rs_config.max_residual_rad) {
        triad_usable = 1;
    }
}

// 3. State Initialization / Reset on Fault Latch Logic
unint32 current_outage = rs_state.outage;

// Determine candidates based on usability
rs_source_t primary_src = RS_NONE;
rs_source_t candidate_src = RS_NONE;

// Default: if no primary held, pick available.
if (rs_state.primary == RS_NONE) {
    if (star_usable) {
        primary_src = RS_STAR;
    } else if (triad_usable) {
        primary_src = RS_TRIAD;
    }
} else {
    primary_src = rs_state.primary;
}

// Identify the alternative candidate
if (primary_src == RS_STAR) {
    if (triad_usable) candidate_src = RS_TRIAD;
} else if (primary_src == RS_TRIAD) {
    if (star_usable) candidate_src = RS_STAR;
}

// Loss of primary switch immediately
if (primary_src != RS_NONE) {
    int primary_is_usable = 0;
    if (primary_src == RS_STAR && star_usable) primary_is_usable = 1;
    if (primary_src == RS_TRIAD && triad_usable) primary_is_usable = 1;

    if (!primary_is_usable) {
        // Immediate switch
        if (candidate_src != RS_NONE) {
            primary_src = candidate_src;
            rs_state.candidate_good = 0; 
        } else {
            // No backup available
            primary_src = RS_NONE;
        }
    }
}

// Switch Confirmation Logic
if (primary_src != RS_NONE && candidate_src != RS_NONE) {
    double p_res = (primary_src == RS_STAR) ? rs_input.star_residual_rad : rs_input.triad_residual_rad;
    double c_res = (candidate_src == RS_STAR) ? rs_input.star_residual_rad : rs_input.triad_residual_rad;

    // Does candidate beat primary by margin?
    if (p_res - c_res >= rs_config.switch_margin_rad) {
        rs_state.candidate_good++;
        if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
            primary_src = candidate_src;
            rs_state.candidate_good = 0; 
        }
    } else {
        rs_state.candidate_good = 0;
    }
} else {
    rs_state.candidate_good = 0;
}

rs_state.primary = primary_src;
rs_state.candidate = candidate_src;
rs_state.candidate_good = rs_state.candidate_good; 

// 4. Fusion vs Primary Selection
adcs_quat_t selected_q = {1, 0, 0, 0};
rs_source_t final_source = RS_NONE;
double disagreement = 0.0;
double w_star = 0.0;
double w_triad = 0.0;

if (star_usable && triad_usable) {
    // Calculate sign-invariant disagreement angle
    double abs_dot = adcs_quat_abs_dot(&star_q_norm, &triad_q_norm);
    if (abs_dot > 1.0) abs_dot = 1.0;
    if (abs_dot < -1.0) abs_dot = -1.0;
    disagreement = acos(abs_dot);

    if (disagreement <= rs_config.fuse_angle_rad) {
        // Fuse
        final_source = RS_FUSED;

        // Sign-align TRIAD to STAR
        adcs_quat_t aligned_triad = triad_q_norm;
        double dot = star_q_norm.w * triad_q_norm.w + star_q_norm.x * triad_q_norm.x + 
                     star_q_norm.y * triad_q_norm.y + star_q_norm.z * triad_q_norm.z;
        if (dot < 0.0) {
            aligned_triad.w = -aligned_triad.w;
            aligned_triad.x = -aligned_triad.x;
            aligned_triad.y = -aligned_triad.y;
            aligned_triad.z = -aligned_triad.z;
        }

        // Weights
        w_star = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
        w_triad = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

        // Weighted Quaternion Sum
        selected_q.w = w_star * star_q_norm.w + w_triad * aligned_triad.w;
        selected_q.x = w_star * star_q_norm.x + w_triad * aligned_triad.x;
        selected_q.y = w_star * star_q_norm.y + w_triad * aligned_triad.y;
        selected_q.z = w_star * star_q_norm.z + w_triad * aligned_triad.z;

        // Normalize
        adcs_quat_normalize(&selected_q, &selected_q);
    } else {
        // Above threshold, publish primary
        final_source = primary_src;
        if (primary_src == RS_STAR) {
            selected_q = star_q_norm;
        } else {
            selected_q = triad_q_norm;
        }
    }
} else if (primary_src == RS_STAR) {
    final_source = RS_STAR;
    selected_q = star_q_norm;
} else if (primary_src == RS_TRIAD) {
    final_source = RS_TRIAD;
    selected_q = triad_q_norm;
} else {
    // Neither usable
    final_source = RS_NONE;
    selected_q = (adcs_quat_t){1, 0, 0, 0};
}

// 5. Outage Handling
if (final_source == RS_NONE) {
    current_outage++;
    if (current_outage >= rs_config.max_outage_cycles) {
        // Latch FAULT
        final_source = RS_FAULT;
        selected_q = (adcs_quat_t){1, 0, 0, 0};
        rs_state.primary = RS_FAULT;
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0;
    } else {
        rs_state.outage = current_outage;
    }
} else {
    // Reset outage if source is available
    if (current_outage > 0) {
         rs_state.outage = 0;
         current_outage = 0;
    }
    // Update previous attitude only if not latched in fault
    if (final_source != RS_FAULT) {
         rs_state.previous_q_bi = rs_output.q_bi;
    }
}

// If we entered FAULT latch in this step, update state to reflect it
if (final_source == RS_FAULT) {
     rs_state.outage = current_outage; 
}

// 6. Output Blending
adcs_quat_t blended_q = {0};

if (final_source != RS_FAULT) {
    // Check sign between selected_q and rs_state.previous_q_bi
    double prev_sel_dot = rs_state.previous_q_bi.w * selected_q.w + 
                          rs_state.previous_q_bi.x * selected_q.x + 
                          rs_state.previous_q_bi.y * selected_q.y + 
                          rs_state.previous_q_bi.z * selected_q.z;

    adcs_quat_t aligned_selected = selected_q;
    if (prev_sel_dot < 0.0) {
        aligned_selected.w = -aligned_selected.w;
        aligned_selected.x = -aligned_selected.x;
        aligned_selected.y = -aligned_selected.y;
        aligned_selected.z = -aligned_selected.z;
